fn find_duplicates(s: Str) -> Vec<Str> {
    let mut seen = vec()
    let mut duplicates = vec()
    for c in chars(s) {
        if contains(seen, c) {
            if !contains(duplicates, c) {
                duplicates = push(duplicates, c)
            }
        } else {
            seen = push(seen, c)
        }
    }
    duplicates
}
