}

struct LetterCount { letter: Str, count: Int }
fn main() {
    let word = "coffee"
    let mut counts = vec()
    for c in chars(word) {
        let found = false
        for i in range(0, len(counts)) {
            let count = unwrap_or(get(counts, i), LetterCount { letter: "", count: 0 })
            if count.letter == c {
                counts = push(counts, LetterCount { letter: clone(c), count: count.count + 1 })
                found = true
                break
            }
        }
        if !found {
            counts = push(counts, LetterCount { letter: clone(c), count: 1 })
        }
    }
    for count in counts {
        if count.count > 1 {
            print_str(count.letter)
        }
    }
}

