fn count_exceeding(v: Vec<Int>, threshold: Int) -> Int {
    let mut count = 0
    for x in v {
        if x > threshold {
            count = count + 1
        }
    }
    count
}
fn max_reading(v: Vec<Int>) -> Option<Int> {
    let mut max = None
    for x in v {
        match clone(max) {
            Some(current_max) => {
                if x > current_max {
                    max = Some(x)
                }
            },
            None => {
                max = Some(x)
            },
        }
    }
    max
}
